% Script for running LUKE
%
% This script is automatically generated by irunluke_jd.
% by J. Decker (joan.decker@cea.fr) and Y. Peysson (yves.peysson@cea.fr)
%
clear all
clear mex
clear functions
close all
warning('off','all')
pause(1)
%
% simulation
%
basestr = 'TS';
shotnum = '32299';
shotime = '100.1733';
%
scenario = 'fluct_Npar0_l_scan';% for batch savename
p_opt = -1;% Figure printing or saving option (-1) none (0) printer (1) printer & file (2) file
%
% remote computing parameters
%
remnum = 1;% remote profile number. Use 0 for local sequential calculations
remtimout = 0;% timeout for remote calculations, in minutes. Use (0) to return later and check results by running this script again
rempause = 1;% pause between job checks (in minutes) (only for remtimout > 0)
remdebugmode = 0;% debug mode (0) off (1) on
remclean = 2;% clean job files/folders : both on remote and local (2), only on remote (1) or not at all (0)
%
% distributed computing parameters
%
mdce_mode_coll_dke_jd = 0;% mdce mode for wave_solver_yp : (0) none (1) jobs (2) dcluke (3) parfor (-remnum) remote on profile remnum
mdce_mode_eecoll_dke_yp = 0;% mdce mode for wave_solver_yp : (0) none (1) jobs (2) dcluke (3) parfor (-remnum) remote on profile remnum
mdce_mode_rfdiff_dke_jd = 0;% mdce mode for rfdiff_dke_jd  : (0) none (1) jobs (2) dcluke (3) parfor (-remnum) remote on profile remnum
mdce_mode_wave_solver_yp = 0;% mdce mode for wave_solver_yp : (0) none (1) jobs (2) dcluke (3) parfor (-remnum) remote on profile remnum
mdce_mode_main_C3PO_jd = 0;% mdce mode for main_C3PO_jd : (0) none (1) jobs (2) dcluke (3) parfor (-remnum) remote on profile remnum
%
% backup & save options
%
opt.save = 0;% (1): save LUKE_RESULTS or return error (0): return results or error
opt.fields = NaN;% selected fields in returned lukestructs. Use NaN for all fields
opt.backup = -1;% (1) save fluctuation time steps (0) do not save
opt.waves = 1;% (1) save waves at each time step (0) do not save
%
% N//0 Fluctuation model
%
% Note : The tail spectrum can be described either in a static mode (if
% dtn_fluct_correlation_npar0_lh = Inf) or in a fluctuating mode (if
% dtn_fluct_correlation_npar0_lh < Inf).
%
dtn_fluct_correlation_npar0_lh = 10;% statistical autocorrelation time (normalized to the electron collision time)
tail_mode = 3;% mode for tail spectrum : (0) no tail model, (1)  Gaussian, (2) Linear, (3) calc_tail_jd
%
fwhm_in = 0.4;% Gaussian model. If fwhm_npar0 is 0 the width is dnpar_antenna. (tail_mode = 1 only)
%
Nparmax_tail_in = 0;% npar0 extend from npar_antenna to Nparmax_tail. If Nparmax_tail is 0, it is calculated by the code in main_rayinit_launch_jd.m -> 6.5/sqrt(Te0)
opt_tail_in = 0;% Final power fraction of the tail @ Nparmax_tail.
n_tail_in = 5;% number of lobes to describe the tail. If n_tail = 0, no tail up to Nparmax_tail (tail_mode = 3 only). 
P_tail_in = NaN;% Power fraction in the tail. If NaN, it is calculated from n_tail and opt_tail (tail_mode = 3 only). 
%
dnpar0_tail = 1;% Adjust (1) or not (0) the initial dNpar0 such that intial and tail lobes have the same width (tail_mode = 3 only).
% 
% Note : tn is adjusted for a direct comparison with the fluctuation case
%   o imaginary tn and dtn are defined with respect to fluctuation times :
%       - tn = 100i -> 100 fluctuation phase changes
%       - dtn = 1i  -> one internal main_dke_yp iteration between two phase changes
%   o real tn and dtn are defined with respect to collision times
%
tn = 100i;%Total normalized integration time. As an imaginary number, dkeparam.tn prescribes the number of fluctuation iterations
Nfluct = 1;%ratio of LUKE internal evolution time to fluctuation time (set to 1 to adjust LUKE time step to fluctuation time step)
dtn = 1i;% LUKE internal time step. As an imaginary number, dkeparam.dtn prescribes the number of internal time steps
%
% *********************** Specify LUKE structures *****************************
%
locid_simul = '';%Simulation ID
path_simul = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_dkepath = '';%For all paths used by DKE solver
path_dkepath = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_equil = [basestr,'_',shotnum,'_',shotime];%For plasma equilibrium
path_equil = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_dkeparam = 'LH_RT';%For DKE code parameters
path_dkeparam = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_dkedisplay = 'NO_DISPLAY';%For output code display
path_dkedisplay = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_ohm = '';%For Ohmic electric contribution
path_ohm = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
ids_wavestruct = {'C3PO_LH_C3_ne3'};%For RF waves contribution (put all the type of waves needed)
paths_wavestruct = {''};%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_transpfaste = 'ES_0_Dr0_0.2';%For fast electron radial transport
path_transpfaste = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
id_ripple = '';%For fast electron magnetic ripple losses
path_ripple = '';%if nothing is specified, the working directory is first used and then MatLab is looking in all the path
%
%************************************************************************************************************************************
%
[dkepath,equil,dkeparam,dkedisplay,ohm,wavestructs,transpfaste,ripple] = load_structures_yp('dkepath',id_dkepath,path_dkepath,'equil',id_equil,path_equil,'dkeparam',id_dkeparam,path_dkeparam,'dkedisplay',id_dkedisplay,path_dkedisplay,'ohm',id_ohm,path_ohm,'wavestructs',ids_wavestruct,paths_wavestruct,'transpfaste',id_transpfaste,path_transpfaste,'ripple',id_ripple,path_ripple);
%
%************************************************************************************************************************************
%
dkeparam.timevol = 1;%to calculate time evolution of moments
dkeparam.opt_struct = 1;% (0) select only main fields from structures (not compatible with fluctuations); (1) select all fields; (2) also select ZXYD_rf
dkeparam.tn = tn;% as an imaginary number, dkeparam.tn prescribes the number of fluctuation iterations
dkeparam.dtn = dtn;% internal LUKE time step. As an imaginary number, dkeparam.dtn prescribes the number of internal time steps
dkeparam.Nfluct = Nfluct;%ratio of LUKE internal evolution time to fluctuation time (set to 1 to adjust LUKE time step to fluctuation time step)
%
dkeparam.clustermode.coll_dke_jd.scheduler.mode = mdce_mode_coll_dke_jd;%MatLab distributed computing environment disabled (0), enabled with the dedicated toolbox (1), enabled with a private method (2) for the function coll_dke_jd.m (MDC toolbox must be installed for option 1)
dkeparam.clustermode.eecoll_dke_yp.scheduler.mode = mdce_mode_eecoll_dke_yp;%MatLab distributed computing environment disabled (0), enabled with the dedicated toolbox (1), enabled with a private method (2) for the function coll_dke_jd.m (MDC toolbox must be installed for option 1)
dkeparam.clustermode.wave_solver_yp.scheduler.mode = mdce_mode_wave_solver_yp;%MatLab distributed computing environment disabled (0), enabled with the dedicated toolbox (1), enabled with a private method (2) for the function coll_dke_jd.m (MDC toolbox must be installed for option 1)
dkeparam.clustermode.rfdiff_dke_jd.scheduler.mode = mdce_mode_rfdiff_dke_jd;%MatLab distributed computing environment disabled (0), enabled with the dedicated toolbox (1), enabled with a private method (2) for the function coll_dke_jd.m (MDC toolbox must be installed for option 1)
%
lukestructs = {};
%
for fwhm = fwhm_in,%scan random width (Gaussian model)
    for opt_tail_0 = opt_tail_in,%scan random width (Tail model)
        for Nparmax_tail = Nparmax_tail_in,%scan upper limit in Npar of the tail (linear or calculated tail model)
            for n_tail = n_tail_in,%scan number of lobes in the tail (linear or calculated tail model)
                for P_tail = P_tail_in,%scan power fraction in the tail (linear or calculated tail model)
                    %
                    % Perturbation of the launched npar for the LH wave only (simulate possible diffraction of the LH wave in the SOL by edge density fluctuations)
                    %
                    tail.dtn = dtn_fluct_correlation_npar0_lh;% Note : from Gaussian time correlation model - see calc_dtn_fluct_jd - dtn_fluct_npar0_lh = 2.14*dtn_fluct_correlation_npar0_lh (if dtn_fluct_npar0_lh is Inf, no fluctuations)
                    tail.mode = tail_mode;% mode for tail spectrum : (0)  Gaussian, (1) Linear, (2) calc_tail_jd
                    %
                    tail.bfwhm = fwhm;%Gaussian distribution for npar0 around npar_antenna given in the launch structure. If bfwhm is 0, the width is dnpar_antenna.
                    %
                    tail.bNparmax_tail = Nparmax_tail;%npar0 extend from npar_antenna to Nparmax_tail. If Nparmax_tail is NaN or empty, it is calculated by the code in main_rayinit_launch_jd.m -> 6.5/sqrt(Te0)
                    tail.bn_tail = n_tail;%number of lobes to describe the tail. If n_tail = 0, no tail up to Nparmax_tail (no used if linear_tail is chosen) 
                    tail.bP_tail = P_tail;%Power fraction in the tail. If NaN, it is calculated from n_tail and opt_tail (no used if linear_tail is chosen) 
                    tail.bopt_tail = opt_tail_0 + dnpar0_tail*1i;%Final power fraction of the tail @ Nparmax_tail (+1i) Adjust initial dNpar0 such that initial and tail lobes have the same width
                    %
                    if ~isempty(locid_simul),
                        locid_simul_tail = [make_tail_simulid_jd(tail),'_',locid_simul];
                    else
                        locid_simul_tail = make_tail_simulid_jd(tail);
                    end
                    %
                    for iw = 1:length(wavestructs),
                        wavestructs{iw}.launch.tail = tail;
                        wavestructs{iw}.C3POparam.clustermode.main_C3PO_jd.scheduler.mode = mdce_mode_main_C3PO_jd;%MatLab distributed computing environment disabled (0), enabled with the dedicated toolbox (1), enabled with a private method (2) for the function coll_dke_jd.m (MDC toolbox must be installed for option 1)
                    end
                    %
                    lukestruct.simul.locid = locid_simul_tail;
                    lukestruct.equil = equil;
                    lukestruct.dkeparam = dkeparam;
                    lukestruct.dkedisplay = dkedisplay;
                    lukestruct.ohm = ohm;
                    lukestruct.waves = '';
                    lukestruct.wavestructs = wavestructs;
                    lukestruct.transpfaste = transpfaste;
                    lukestruct.ripple = ripple;
                    lukestruct.opt = opt;
                    %
                    lukestructs = [lukestructs,lukestruct];
                    %
                end
            end
        end
    end
end
%
dkepath.remnum = remnum;
dkepath.remtimout = remtimout;
dkepath.rempause = rempause;
dkepath.debugmode = remdebugmode;
dkepath.clean = remclean;
%
lukestructs = run_lukert(lukestructs,dkepath);
%
% ---------------------------------------------- Save batch results ----------------------------------------------
%
% Note : opt.save = 0, results or jobs are saved in file LUKE_BATCH_...
%
% To process and save individual LUKE_RESULTS files, use : 
% >> completed_jobs = load_batch_jd('LUKE_BATCH_....mat')
%
% If not all jobs are completed, use again with :
% >> completed_jobs = load_batch_jd('LUKE_BATCH_....mat',completed_jobs)
%
if opt.save == 0,
    save_batch_jd(lukestructs,dkepath,scenario)
end
%
